(()=>{
const projects={adda:['عضّة','ADDA','مطاعم وتجربة طلب تفاعلية','Restaurant & interactive ordering'],skyward:['سكاي وارد','Skyward Travel','سياحة واستكشاف الوجهات','Travel & destination discovery'],caffaino:['كافاينو','CAFFAINO','قهوة وتجربة بصرية','Coffee & visual storytelling']};
const dialog=document.querySelector('.project-dialog'),frame=dialog.querySelector('iframe'),full=dialog.querySelector('.project-full'),close=dialog.querySelector('button');let active=null,opener;
const en=()=>document.documentElement.lang==='en';
function localize(){Object.entries(projects).forEach(([id,p])=>{document.querySelector('[data-project-name="'+id+'"]').textContent=p[en()?1:0];document.querySelector('[data-project-category="'+id+'"]').textContent=p[en()?3:2];const a=document.querySelector('[data-preview="'+id+'"]');a.setAttribute('aria-label',(en()?'Preview ':'معاينة ')+p[en()?1:0]);a.querySelector('.project-preview-label').textContent=en()?'Try the website ↗':'جرّب الموقع ↗';});document.querySelector('.folder-title').textContent=en()?'Our work':'أعمالنا';document.querySelector('.folder-sub').textContent=en()?'3 brands · Open & explore':'٣ براندات · افتح واستكشف';full.textContent=en()?'Open full website ↗':'فتح الموقع كاملًا ↗';close.setAttribute('aria-label',en()?'Close preview':'إغلاق المعاينة');if(active){document.querySelector('#project-dialog-title').textContent=projects[active][en()?1:0];frame.title=(en()?'Preview: ':'معاينة: ')+projects[active][en()?1:0];}}
document.querySelectorAll('[data-preview]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();opener=a;active=a.dataset.preview;frame.src=a.href;full.href=a.href;localize();dialog.showModal();document.body.style.overflow='hidden';}));
close.onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{frame.removeAttribute('src');document.body.style.overflow='';opener?.focus();});new MutationObserver(localize).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});localize();
const folder=document.querySelector('.work-folder'),trigger=folder.querySelector('.folder-front'),cloud=folder.querySelector('.folder-cloud');let timer;
function setOpen(open){folder.dataset.open=String(open);trigger.setAttribute('aria-expanded',String(open));cloud.inert=!open;}
setOpen(false);trigger.addEventListener('click',()=>setOpen(folder.dataset.open!=='true'));
folder.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){clearTimeout(timer);setOpen(true);}});
folder.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')timer=setTimeout(()=>{if(!folder.contains(document.activeElement)&&!dialog.open)setOpen(false);},300);});
folder.addEventListener('keydown',e=>{if(e.key==='Escape'){setOpen(false);trigger.focus();}});
document.addEventListener('pointerdown',e=>{if(!folder.contains(e.target)&&!dialog.open)setOpen(false);});
})();